class Circle{
	constructor(x, y, r){
		var options ={
			friction: 0,
			restituion: 0.9
		}
		this.body= Bodies.circle(x, y, r, options);
		this.size= r*2
		World.add(engine.world, this.body)
		this.color=random(colors)
	}

	cut(){
		if(this.body.position.y>height+100){
			{
			World.remove(engine.world, this.body)
      let index = Circles.indexOf(this);
      Circles.splice(index, 1);
    }
		}
	}

	show(){
		//fill(this.color)
		fill('#E8E9EB')
		rectMode(CENTER)
		push()
			translate(this.body.position.x, this.body.position.y)
	circle(0, 0, this.size)
	fill(255, 50)
	circle(0, 0, this.size*1.4)
	pop()
	}
}

class Boundary{
	constructor(x, y, w, a){
		var options ={
			friction: 0.9,
			restituion: 0.1,
			angle: a,
			isStatic: true
		}
		this.body= Bodies.circle(x, y, w, options);
		this.width= w
		//this.height=h
		World.add(engine.world, this.body)
		this.color=random(colors)
	}

	show(){
		fill('#E0DFD5')
		rectMode(CENTER)
		push()
			translate(this.body.position.x, this.body.position.y)
			rotate(this.body.angle)
	circle(0, 0, this.width*2)
	pop()
	}
}


class Flipper{
	constructor(x, y, w, h){
		var options ={
			friction: 0,
			restituion: 0			
		}

		this.body= Bodies.rectangle(x, y, w, h);

		var constraint = Constraint.create({
        pointA: { x: x, y: y },
        bodyB: this.body,
			stiffness: 0.8,
			damping: 1
    });
		this.anchorX=x
		this.anchorY=y
		this.width= w
		this.height=h
		World.add(engine.world, [this.body, constraint])

	}

	show(){
		//fill(this.color)
		fill('#313638')
		rectMode(CENTER)
		push()
			translate(this.body.position.x, this.body.position.y)
			rotate(this.body.angle)
		fill(255, 20)
	ellipse(0, 0, this.width)
		fill('#313638')
	rect(0, 0, this.width, this.height, 60)
	pop()
		//stroke(255)
		//line(this.body.position.x, this.body.position.y, this.anchorX, this.anchorY)
		noStroke()
	}
}

